  prod: (b) => abrirProducto(b.dataset.id),
  vender: (b) => { const p = S.idx[b.dataset.id]; if (p) abrirForma('venta', { inicial: [{ id: p.id, cant: 1, precio: p.precio ? String(p.precio) : '' }] }); },
  ventas: () => abrirVentas(),
